import { cacheTag } from 'next/cache'
import { readFile, writeFile } from 'node:fs/promises'
import path from 'node:path'

export type Post = {
  id: string
  title: string
  content: string
}

const postsFile = path.join(process.cwd(), 'posts.json')

async function readPosts(): Promise<Post[]> {
  try {
    const data = await readFile(postsFile, 'utf8')
    return JSON.parse(data) as Post[]
  } catch {
    return []
  }
}

export async function getPosts(): Promise<Post[]> {
  'use cache'
  cacheTag('posts')
  return readPosts()
}

export async function addPost(title: string, content: string): Promise<Post> {
  const posts = await readPosts()
  const post: Post = {
    id: crypto.randomUUID(),
    title,
    content,
  }
  posts.push(post)
  await writeFile(postsFile, JSON.stringify(posts, null, 2))
  return post
}

